    while (i < input.length()) {
        char c = input.charAt(i);
        if (c == '\\') {
            if (i + 1 < input.length()) {
                char nextChar = input.charAt(i + 1);
                if (nextChar == '.') {
                    result.append('.');
                    i += 2; // Skip the backslash and the dot
                } else {
                    result.append(c); // Keep the backslash if not followed by a dot
                    i++;
                }
            } else {
                result.append(c); // If backslash is the last character, keep it
                i++;
            }
        } else {
            result.append(c);
            i++;
        }
    }
    return result.toString();
}

