    while (i < str.length()) {
        char c = str.charAt(i);
        if (c == '\\') {
            if (i + 1 >= str.length()) {
                throw new Exception("Invalid escape sequence at end of string");
            }
            char nextChar = str.charAt(i + 1);
            switch (nextChar) {
                case 'b':
                    result.append('\b');
                    break;
                case 't':
                    result.append('\t');
                    break;
                case 'n':
                    result.append('\n');
                    break;
                case 'f':
                    result.append('\f');
