    long result = 0;
    int shift = 0;
    byte b;
    do {
        b = readRawByte();
        result |= (long) (b & 0x7F) << shift;
        shift += 7;
        if (shift > 63) {
            throw new IOException("Invalid varint");
        }
    } while ((b & 0x80) != 0);
    return result;
}

